\label{noncommutative jol}
	Let $G$ be a locally compact second countable group. If there exists an action of $G$ on a von Neumann algebra $N$ with a faithful normal state $\varphi$ that is $G$-invariant, such that the action is strongly mixing and has a nontrivial asymptotically invariant sequence, then $G$ has the Haagerup property.
	\\
	Conversely, if $G$ has the Haagerup property, then it has such an action on the following von Neumann algebras:
	\begin{enumerate}
		\item $N = R$ (where $R$ is the hyperfinite {\normalfont\Romannum{2}}$_1$ factor);
		\item $N = R\otimes \operatorname{B}(\ell^2)$;
		\item $N = R_\lambda$ (where $R_\lambda$ is the Powers factor).
	\end{enumerate}

\label{thm:main}
	Let $G$ be a locally compact second countable group and let $N$ be a von Neumann algebra. If there exists an action of $G$ on $N$ that is $C_0$ and has an almost invariant sequence, then $G$ has the Haagerup property.
	Conversely, if $G$ has the Haagerup property, then there exists von Neumann algebras $N$ of every type for which there exists an action of $G$ on $N$ that is $C_0$ and has an almost invariant sequence.

\label{THM DJZ}
	Let $G$ be a locally compact, second countable group. Then it has the Haagerup property if and only if it admits an action by Borel automorphisms on a measure space $(\Omega,\mu)$ such that $\mu$ is $\sigma$-finite, $G$-invariant and satisfies the following two additional properties:
	\begin{enumerate}
		\item for all measurable subsets $A,B\subset \Omega$ such that $0<\mu(A),\mu(B)<\infty$, the function $g\mapsto \mu(gA\cap B)$ is $C_0$, i.e. $(\Omega,\mathcal{B}, \mu,G)$ is a $C_0$-dynamical system;
		\item There exists a sequence of subsets $(A_n)_{n\ge 1}\subset \mathcal{B}$ with measure $\mu(A_n)=1$ for all $n$ such that for all compact subsets $K$ of $G$ we have 
\begin{equation}\label{Property3}
\lim_{n\rightarrow \infty} \sup_{g\in K} \mu(gA_n\Delta A_n)=0.
\end{equation}
	\end{enumerate}

\label{representation}
	Let $G$ be an l.c.s.c.\ group with an action $\alpha$ on a von Neumann algebra $N$.
	The action $\alpha$ extends to a unitary representation on $\operatorname{L}^2(N,\varphi)$ if and only if $\alpha$ preserves the weight $\varphi$, that is $\varphi\circ \alpha_g=\varphi$, and for every $x\in \mathfrak{n}_{\varphi}$ we have that the maps $g \mapsto \varphi(x^* \alpha_g(x))$ are measurable.

\label{def:C0}
	Let $G$ be an l.c.s.c. group with an action $\alpha$ on a von Neumann algebra $N$.
	The action $\alpha$ is $C_0$ for $\varphi$ if its extension to $\operatorname{L}^2(N,\varphi)$ is a unitary representation and 
	\begin{equation}\label{property1}
	\lim_{g\rightarrow \infty} \varphi(\alpha_g(x)y)=0 \quad \forall x,y \in \mathfrak{n}_{\varphi}.
	\end{equation}
	A sequence of projections $(e_k)_{k \ge 1}\subset \mathfrak{n}_{\varphi}$ is said to be an almost invariant sequence for $\alpha$ and $\varphi$ if $\|e_k\|_{\varphi}=1$ for all $k$ and 
	\begin{equation}\label{property2}
	\lim_{k\rightarrow \infty} \sup_{g\in K} \| \alpha_g(e_k)-e_k\|_{\varphi}=0,
	\end{equation}
	for all compact subsets $K$ of $G$.

We begin to show the existence of a sequence of almost invariant projections. As $G$ has the Haagerup property, there exists, by \cref{Haagerp Definition}, a sequence of unit vectors $(\xi_n)_n$ in $\mathcal{H}$ such that for every compact sets $K$ of $G$:
	$$\lim_{n\rightarrow \infty} \sup_{g\in K} \|\pi(g)\xi_n-\xi_n\|=0.$$
	Set $P_n=\Psi(\xi_n\otimes \xi_n)$. Then we have:
	\begin{align*}
	\operatorname{Tr}(P_n^*P_n)=\sum_k\langle P_ne_k,P_ne_k\rangle&=\sum_k\langle \langle e_k, \xi_n\rangle \xi_n,  \langle e_k, \xi_n\rangle \xi_n \rangle\\
	&=\sum_k | \langle e_k, \xi_n\rangle|^2=\|\xi_n\|^2=1,
	\end{align*}
	where we used Parseval's identity. Moreover
	\begin{align*}
	\alpha_g(P_n)(\eta)&=\pi(g)P_n\pi(g^{-1})(\eta)\\
	&=\langle \eta, \pi(g) \xi_n\rangle \pi(g) \xi_n\\
	&=\Psi(\pi(g)\xi_n \otimes \pi(g)\xi_n)(\eta).
	\end{align*}
	Therefore:
	\begin{align*}
	\|\alpha_g(P_n)-P_n\|_{\operatorname{Tr}}^2&=\|\pi(g)\xi_n \otimes \pi(g)\xi_n - \xi_n\otimes\xi_n\|^2\\
	&=\left(\|\pi(g)\xi_n\|^4-2\text{Re}\left(\langle\pi(g)\xi_n,\xi_n\rangle^2\right)+ \|\xi_n\|^4\right)\\
	&=2\left(1-\text{Re}\left(\langle\pi(g)\xi_n,\xi_n\rangle^2\right)\right).\\
	\end{align*}
	Hence for every compact sets $K$ of $G$ we have:
	$$\lim_{n\rightarrow \infty} \sup_{g\in K} \|\alpha_g(P_n)-P_n\|_{\operatorname{Tr}}=0.$$
	It remains to show that $\alpha$ is $C_0$ for $\operatorname{Tr}$. First take elements of the form $\xi_1\otimes \eta_1, \xi_2\otimes \eta_2\in \mathcal{H}\overline{\otimes} \mathcal{H}$ and consider their image by $\Psi$ denoted $T_{\xi_1,\eta_1},T_{\xi_2,\eta_2} \in \mathfrak{n}_{\operatorname{Tr}}$. By Cauchy-Schwarz inequality we have:
	\begin{align*}
	\operatorname{Tr}(T_{\xi_1,\eta_1}^* \alpha_g(T_{\xi_2,\eta_2}))&=\sum_k \langle \pi(g)T_{\xi_2,\eta_2}\pi(g)^*e_k, T_{\xi_1,\eta_1}e_k\rangle\\
	&=\sum_k \langle \pi(g)\langle\pi(g^{-1})e_k, \xi_2\rangle \eta_2, \langle e_k, \xi_1\rangle \eta_1\rangle\\
	&=\langle\pi(g)\eta_2,\eta_1\rangle \sum_k \langle \pi(g^{-1})e_k,\xi_2\rangle\langle e_k, \xi_1\rangle\\
	&\le \langle\pi(g)\eta_2,\eta_1\rangle \|\xi_1\|\|\pi(g)\xi_2\|.
	\end{align*}
	As $\pi$ is a unitary $C_0$-representation, then we have $$\lim_{g\rightarrow \infty}\operatorname{Tr}(T_{\xi_1,\eta_1}^* \alpha_g(T_{\xi_2,\eta_2}))=0.$$
	Now take $T_1,T_2\in \mathfrak{n}_{\operatorname{Tr}}$. By Proposition \ref{IsomorphismHilbert} there exists $\xi,\eta\in \mathcal{H}\overline{\otimes} \mathcal{H}$ which represent $T_1,T_2$. Moreover for $\varepsilon>0$ fixed, there exists sequences $(\xi_n),(\eta_n)\subset \mathcal{H}$ such that:
	\begin{enumerate}
		\item $\| \xi - \sum_{n=1}^{N_{\varepsilon}} e_n \otimes \xi_n \|\le \varepsilon;$
		\item $\| \eta - \sum_{n=1}^{N_{\varepsilon}} e_n \otimes \eta_n \|\le \varepsilon.$
	\end{enumerate}
	Thus
	\begin{align*}
	\operatorname{Tr}(T_1^*\alpha_g(T_2))&=\langle \Psi\left(\xi -\sum_{n=1}^{N_{\varepsilon}}e_n \otimes \xi_n\right), \alpha_g(\Psi(\eta))\rangle_{\operatorname{Tr}}+\langle \Psi\left(\sum_{n=1}^{N_{\varepsilon}} e_n \otimes \xi_n\right), \alpha_g(\Psi(\eta))\rangle_{\operatorname{Tr}}\\
	&=\langle \Psi\left(\xi-\sum_{n=1}^{N_{\varepsilon}}e_n \otimes \xi_n\right), \alpha_g(\Psi(\eta))\rangle_{\operatorname{Tr}} +\\
	&\langle \Psi\left(\sum_{n=1}^{N_{\varepsilon}} e_n \otimes \xi_n\right), \alpha_g\left(\Psi\left(\eta-\sum_{n=1}^{N_{\varepsilon}} e_n\otimes \eta_n\right)\right)\rangle_{\operatorname{Tr}}\\
	&+\langle \Psi\left(\sum_{n=1}^{N_{\varepsilon}} e_n\otimes \xi_n\right), \alpha_g\left(\Psi\left(\sum_{n=1}^{N_{\varepsilon}}e_n\otimes \eta_n\right)\right)\rangle_{\operatorname{Tr}}
	\end{align*}
	Hence by Cauchy Schwarz and using that $\alpha$ is $C_0$ for the elements $T_{\xi_i,\eta_i}$, there exists a compact set $K$ of $G$ such that for all $g\in G\setminus K$ :
	\begin{align*}
	\operatorname{Tr}(T_1^*\alpha_g(T_2))&\le \varepsilon \|T_2\|_{\operatorname{Tr}} + \varepsilon\sqrt{\|T_1\|_{\operatorname{Tr}}+\varepsilon} +\sum_{i,j=1}^{N_{\varepsilon}} \frac{\varepsilon}{N_{\varepsilon}^2}\\
	&\le \varepsilon(1+\|T_2\|_{\operatorname{Tr}}+\sqrt{\|T_1\|_{\operatorname{Tr}}+\varepsilon}).
	\end{align*}

\label{remarkexempleprojections}
	In the context of Theorem \ref{THM DJZ}, this construction gives a $C_0$-action on $(\operatorname{B}(\operatorname{L}^2(\Omega,\mu)),\operatorname{Tr})$ relatively to the permutation representation $\pi_{\Omega}$. Moreover an almost invariant sequence of projections is given by the family $(A_n)_n\subset \mathcal{B}$ considering $$P_n(f)=\frac{\langle f,\chi_{A_n}\rangle}{\mu(A_n)}\chi_{A_n},$$
	for any $f\in L^2(\Omega).$

To prove this proposition we need an observation. Let $F$ be a finite subset of $\Gamma$ and consider an element in $N$ of the form  $$\sum_{s\in F} x(s)y(s).$$
	Then we have that:
	\begin{equation}\label{normality}
	\varphi\left(\sum_{s\in F} x(s)y(s)\right)=\sum_{s\in F} \varphi(x(s)y(s)).
	\end{equation}
	As $\varphi\left(\sum_{s\in F} x(s)y(s)\right)$ can be derived from:
	\begin{align*}
	\varphi\left( \sum_{s\in F} (x(s) + y(s))^*(x(s)+y(s))\right),\; \varphi\left( \sum_{s\in F}  y(s)^*y(s)\right),\; \varphi\left( \sum_{s\in F} x(s)^*x(s)\right),
	\end{align*}
 we can prove that the real and the imaginary parts of the left hand side are equal to those in the right hand side in (\ref{normality}).

\label{prop:tensor}
	Let $G$ be an l.c.s.c.\ group with the Haagerup property and let $N$ and $M$ be von Neumann algebras with faithful, normal, semi-finite weights $\varphi_N$ and $\varphi_M$ such that $G$ has a $C_0$-action on $N$ with an almost invariant sequence and $G$ has an action on $M$ that also has an almost invariant sequence and that extends to a unitary representation on $\operatorname{L}^2(M,\varphi_M)$.
	Then $G$ has a $C_0$-action on $N\overline{\otimes} M$ with an almost invariant sequence.

\label{Koopman}
Let $\sigma:G\curvearrowright X$ a nonsingular action on a space $X$ and $\pi:G\curvearrowright L^2(X)$ the associated Koopman representation. Then the following are equivalent: 
\begin{enumerate}
\item[(i)] $\lim_{g\to \infty} \langle \pi(g)\xi,\xi\rangle=0$ for some faithful $\xi \in L^2(X)^{+}$.
\item[(ii)] $\pi$ is mixing.
\end{enumerate}

\label{THM DJZ 2}
	Let $G$ be a locally compact, second countable group. Then it has the Haagerup property if and only if it admits an action by Borel automorphisms on a measure space $(\Omega,\mu)$ such that $\mu$ is $\sigma$-finite, $G$-invariant and satisfies the following two additional properties:
	\begin{enumerate}
		\item for all measurable subsets $A,B\subset \Omega$ such that $0<\mu(A),\mu(B)<\infty$, the function $g\mapsto \mu(gA\cap B)$ is $C_0$, i.e. $(\Omega,\mathcal{B}, \mu,G)$ is a $C_0$-dynamical system;
		\item There exists a sequence of unit vectors $(\xi_n)_{n\ge 1}\subset L^2(\Omega,\mu)^+$ such that for all compact subsets $K$ of $G$, one has 
		$$
\lim_{n\rightarrow \infty} \sup_{g\in K} \langle \pi_{\Omega}(g)\xi_n,\xi_n\rangle=1.
$$
	\end{enumerate}
	Moreover if $G$ is non-periodic, then $C_0$-dynamical system may be assumed to be ergodic.

{(Proposition 2.7, \cite{amine2})}\label{2.7 Amine}
Let $(\xi_i+H_i)_{i\in I}$ by a family of closed affine subspaces of a real Hilbert space $H$. Write $K=\bigcap_{i\in I} H_i$, $M=\bigcap_{i\in I}(\xi_i +H_i)$, $A=\bigcap_{i\in I} \mathcal{M}(\xi_i+H_i)$.
\begin{enumerate}
\item If $M=\emptyset$, then $A=L^{\infty}(\hat{K})\otimes 1.$
\item If $\eta \in M$, then $M=\eta +K$ and $A=\mathcal{M}(\eta +K)$.
\end{enumerate}

\label{example groupe libre}
Let $\sigma:\mathbb{F}_2\curvearrowright T_4$ its action on its Cayley graph. Then an explicit example of infinite measure space in the hypothesis of theorem  \cite{delabie2019new} is given by:
$$(\Omega(T_4)\times \mathbb{R}, \mu \otimes \lambda).$$
